import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import * as api from '../api';
import { t } from '../util';
const REASONS = ['spam', 'inappropriate', 'off_topic', 'other'];

/** Report a moment or reply to the moderators. */
export default class ReportModal extends FormModal {
  reason = '';
  detail = '';
  className() {
    return 'MomentReportModal Modal--small';
  }
  title() {
    return t('report.title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, m("div", {
      className: "Form-group"
    }, REASONS.map(reason => m("label", {
      className: "checkbox"
    }, m("input", {
      type: "radio",
      name: "reason",
      checked: this.reason === reason,
      value: reason,
      onchange: () => this.reason = reason
    }), m("strong", null, t(`report.${reason}`)), m("span", {
      className: "helpText"
    }, t(`report.${reason}_help`))))), m("div", {
      className: "Form-group"
    }, m("textarea", {
      className: "FormControl",
      rows: 3,
      maxlength: 1000,
      placeholder: String(t('report.detail')),
      value: this.detail,
      oninput: e => this.detail = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary Button--block",
      loading: this.loading,
      disabled: !this.reason
    }, t('report.submit')))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    api.report(this.attrs.moment.id, this.reason, this.detail).then(() => {
      this.hide();
      app.alerts.show({
        type: 'success'
      }, t('report.done'));
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-moments', 'forum/components/ReportModal', ReportModal);